process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 3 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
gw=http://10.231.1.254:3128
[ "$HTTPS_PROXY" = $gw ] && [ "$https_proxy" = $gw ] && [ "$HTTP_PROXY" = $gw ] && [ "$http_proxy" = $gw ] && [ -z "$NO_PROXY$no_proxy" ] && [ -z "$NODE_USE_ENV_PROXY" ] && echo PROXY_ENV=OK || echo "PROXY_ENV=BAD [$HTTPS_PROXY] [$NO_PROXY]"
grep -qx 'nameserver 10.231.1.254' /etc/resolv.conf && echo RESOLV=GATEWAY || echo RESOLV=OTHER
echo ALLOWED=$(p 1.1.1.1:443)
echo ADJACENT=$(p 1.1.1.2:443)
echo WRONG_PORT=$(p 1.1.1.1:80)
echo OTHER=$(p 8.8.8.8:443)
echo HTTP_WRONG_PORT=$(printf 'GET http://1.1.1.1/ HTTP/1.1\r\nHost: 1.1.1.1\r\n\r\n' | nc -w 3 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2)
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
